import { inspectCookies, SetCookieInspectorError } from '@fodt/set-cookie-inspector';

const report = inspectCookies({
  lines: 'Set-Cookie: __Host-SID=12345; Secure; Domain=site.example; Path=/',
  requestUrl: 'https://site.example/account/login',
  context: 'same-site',
  nowMs: Date.UTC(2026, 9, 6, 12, 0, 0),
  reveal: false,
});

report.cookies[0].decision.outcome; // 'not-stored'
report.cookies[0].decision.reason; // '__Host- needs Secure, no Domain and Path=/ ...'
